# 端侧推理峰值内存估算：为什么峰值会远超模型文件大小。
# 单选题结论：最可能让峰值显著超过模型文件的是
# 「中间激活、临时缓冲区和多分支并发执行」。
# 权重（模型文件）只是常驻的一份，激活与临时缓冲随 batch、序列长度、
# 算子实现（im2col、显式注意力矩阵）成倍放大；多分支并发时这些缓冲
# 还会同时驻留，峰值因此可以达到模型文件的数倍。纯标准库，可直接运行。


def weight_bytes(num_params, bits=8):
    # 模型文件大小的来源：参数量 x 量化位宽。bits 取 4/8/16/32。
    if num_params <= 0 or bits not in (4, 8, 16, 32):
        raise ValueError('num_params 必须为正，bits 取 4/8/16/32')
    return num_params * bits // 8


def kv_cache_bytes(batch, seq_len, layers, hidden, bits=8):
    # 自回归解码的 KV cache：2（K 和 V）x 层数 x batch x 序列 x 隐层。
    if min(batch, seq_len, layers, hidden) <= 0:
        raise ValueError('batch/seq_len/layers/hidden 都必须为正')
    return 2 * layers * batch * seq_len * hidden * (bits // 8)


def activation_bytes(batch, seq_len, hidden, layers, bits=8, fanout=2):
    # 中间激活：按每层一份 fanout 倍隐层的工作集估算。
    if min(batch, seq_len, hidden, layers) <= 0 or fanout < 1:
        raise ValueError('尺寸必须为正，fanout 至少为 1')
    return layers * batch * seq_len * hidden * fanout * (bits // 8)


def temp_buffer_bytes(batch, seq_len, hidden, im2col=False, attn_matrix=False, bits=8):
    # 算子临时缓冲：im2col 展开与显式 SxS 注意力矩阵是端侧最典型的两块。
    total = 0
    if im2col:
        total += batch * seq_len * hidden * 9 * (bits // 8)
    if attn_matrix:
        total += batch * seq_len * seq_len * (bits // 8)
    return total


def peak_memory(num_params, batch, seq_len, hidden, layers,
                bits=8, branches=1, im2col=False, attn_matrix=False):
    # 峰值 = 一份权重 + 每个并发分支各一份工作集 + 一份 KV cache。
    if branches < 1:
        raise ValueError('branches 至少为 1')
    weights = weight_bytes(num_params, bits)
    branch_ws = activation_bytes(batch, seq_len, hidden, layers, bits) + \
        temp_buffer_bytes(batch, seq_len, hidden, im2col, attn_matrix, bits)
    kv = kv_cache_bytes(batch, seq_len, layers, hidden, bits)
    peak = weights + branches * branch_ws + kv
    return {'weights': weights, 'branch_ws': branches * branch_ws,
            'kv_cache': kv, 'peak': peak, 'ratio_to_file': peak / weights}


def option_impact(option):
    # 逐个选项判定：只有 A 会成倍抬高峰值内存。
    table = {
        'A': '抬高：激活/临时缓冲随 batch*序列*隐层增长，多分支还并发多份',
        'B': '几乎无影响：输出类别数只决定最后一层的大小，是常数项',
        'C': '无影响：训练集规模属于训练阶段，端侧推理不读训练集',
        'D': '无影响：标签类别数不进入推理时的内存账',
    }
    return table.get(option.strip().upper(), '未知选项')


def main():
    # 例：1 亿参数、8bit 量化、batch=1、序列 512、隐层 1024、24 层、2 个并发分支。
    report = peak_memory(num_params=100000000, batch=1, seq_len=512,
                         hidden=1024, layers=24, bits=8,
                         branches=2, im2col=True, attn_matrix=True)
    mb = 1024 * 1024
    print('模型文件(权重): %.1f MB' % (report['weights'] / mb))
    print('分支工作集   : %.1f MB' % (report['branch_ws'] / mb))
    print('KV cache     : %.1f MB' % (report['kv_cache'] / mb))
    print('峰值内存     : %.1f MB' % (report['peak'] / mb))
    print('峰值/模型文件: %.2fx' % report['ratio_to_file'])
    for opt in 'ABCD':
        print(opt, option_impact(opt))
    assert report['ratio_to_file'] > 1.0, '峰值应当超过模型文件本身'
    # 边界：最小模型（1 参数、1 层、序列 1）也要有正的权重与合法分解。
    tiny = peak_memory(1, 1, 1, 1, 1, bits=32)
    assert tiny['peak'] >= tiny['weights'] > 0
    print('OK')


if __name__ == '__main__':
    main()
